{"command":"python3 - <<'PY'
import json, urllib.request
URL='http://program:8008/checkpoint'

def checkpoint(line):
    data=json.dumps({'line':line}).encode()
    req=urllib.request.Request(URL,data=data,headers={'Content-Type':'application/json'},method='POST')
    with urllib.request.urlopen(req, timeout=10) as r:
        return json.loads(r.read().decode())

def in_range(resp):
    return 'out of range' not in resp.get('message','').lower()

lo, hi = 1, 1
calls=0
while True:
    resp=checkpoint(hi); calls+=1
    print('probe', hi, resp)
    if in_range(resp):
        lo=hi
        hi*=2
        if hi>1000000:
            hi=1000001
    else:
        break
    if hi==1000001:
        resp=checkpoint(hi); calls+=1
        print('probe', hi, resp)
        break
# total N in [lo, hi-1] if hi out of range. If 1000001 out of range, max 1e6.
low=lo; high=hi-1
while low<high:
    mid=(low+high+1)//2
    resp=checkpoint(mid); calls+=1
    print('bin', mid, resp)
    if in_range(resp):
        low=mid
    else:
        high=mid-1
print('TOTAL', low, 'checkpoint_calls_this_script', calls)
PY"}

